// Controller-only authority. Reads the synthetic worker's persisted owners/files;
// never writes business records or accepts caller-supplied paths/credentials.
import assert from 'node:assert/strict';
import {DatabaseSync} from 'node:sqlite';
import {readFile,readdir,lstat} from 'node:fs/promises';
import {join} from 'node:path';
import {createRequire} from 'node:module';
import {listingReply} from './pipeline-normal-draft.mjs';
const {sha,headerHash}=createRequire(import.meta.url)('./pipeline-route-permit.cjs');
const {assertTrustedWithin,worktreeRoot}=createRequire(import.meta.url)('./trusted-path.cjs');
async function ownedFile(workspace,path,limit){assertTrustedWithin(workspace,path);const stat=await lstat(path);assert.ok(stat.isFile()&&!stat.isSymbolicLink()&&stat.nlink===1&&stat.size>0&&stat.size<=limit,'S10_PRIVATE_FILE');return readFile(path);}
const uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
export async function authorizeNormalRoute({workspace,config,provider,input}){
  assert.ok(workspace,'S10_CONTROLLER_NOT_BOUND');assert.deepEqual(Object.keys(input).sort(),['body','headers','method','url']);assert.ok(typeof input.url==='string'&&new URL(input.url).href===input.url&&!/%(?:2e|2f|5c)|\\|\.\./i.test(input.url),'S10_DYNAMIC_URI');
  assertTrustedWithin(join(worktreeRoot,'.test-data'),workspace);assertTrustedWithin(workspace,join(workspace,'red.sqlite'));
  const bytes=Buffer.from(input.body,'base64');assert.equal(bytes.toString('base64'),input.body);const url=new URL(input.url),headers=new Headers(input.headers),db=new DatabaseSync(join(workspace,'red.sqlite'),{readOnly:true});
  let tasks,drafts,runs,followups;try{tasks=db.prepare('SELECT record_json FROM automatic_listing_tasks').all().map(row=>JSON.parse(row.record_json));drafts=db.prepare('SELECT record_json FROM listing_drafts WHERE record_json IS NOT NULL').all().map(row=>JSON.parse(row.record_json));followups=db.prepare('SELECT record_json FROM listing_followups').all().map(row=>JSON.parse(row.record_json));runs=db.prepare('SELECT record_json FROM image_workflow_runs').all().map(row=>JSON.parse(row.record_json));}finally{db.close();}
  assert.equal(tasks.length,1,'S10_ONE_OWNED_TASK');const task=tasks[0];assert.equal(task.items.length,1);assert.equal(task.sellerId,config.amazon.sellerId);assert.equal(task.mode,'live');const owner=task.items[0];
  let protocol,response;
  if(url.origin==='https://sellingpartnerapi-na.amazon.com'){
    const record=drafts.find(row=>row.draft.id===owner.draftId),draft=record?.draft;assert.ok(draft&&draft.productId===owner.productId&&draft.sku===owner.sku&&draft.sellerId===task.sellerId&&draft.targetId===task.targetId,'S10_DRAFT_OWNER');assert.equal(draft.listingProgram,'haul');
    const operation=input.method==='GET'?'readback':url.searchParams.has('mode')?'preview':'submit';assert.equal(input.method,operation==='readback'?'GET':'PUT');assert.equal(url.pathname,`/listings/2021-08-01/items/${task.sellerId}/${owner.sku}`);
    const query={marketplaceIds:task.marketplaceId,issueLocale:'en_US',...(operation==='preview'?{mode:'VALIDATION_PREVIEW',includedData:'issues'}:operation==='submit'?{includedData:'issues'}:{includedData:'summaries,issues,attributes,offers,fulfillmentAvailability,relationships'})};assert.equal(url.search,'?'+new URLSearchParams(query));
    if(operation==='readback')assert.equal(bytes.length,0);else assert.equal(bytes.toString(),JSON.stringify({productType:draft.schema.productType,requirements:draft.schema.requirements,attributes:draft.attributes}),'S10_DRAFT_WIRE_BODY');
    let signedNow=config.clock;if(operation==='readback'){const raw=headers.get('x-amz-date');assert.match(raw,/^[0-9]{8}T[0-9]{6}Z$/);signedNow=raw.slice(0,4)+'-'+raw.slice(4,6)+'-'+raw.slice(6,8)+'T'+raw.slice(9,11)+':'+raw.slice(11,13)+':'+raw.slice(13,15)+'.000Z';const original=followups.find(row=>row.draftId===draft.id);assert.ok(original?.lastAttemptAt);assert.ok(Math.abs(Date.parse(signedNow)-Date.parse(original.lastAttemptAt))<5000,'S10_READBACK_CLOCK_OWNER');}
    protocol={kind:'amazon',operation,sellerId:task.sellerId,sku:owner.sku,accessToken:'s10-normal-amazon-token',now:signedNow,...(operation==='readback'?{}:{bodySha256:sha(bytes)})};response={json:listingReply(operation,{sku:owner.sku})};
  }else if(url.origin==='https://htc.185858.xyz'){
    assert.equal(input.method,'GET');assert.equal(bytes.length,0);assert.ok(url.pathname.startsWith('/AAA/'));const remotePath='/s10/'+url.pathname.slice(5),upload=provider.ledger().findLast(row=>row.event==='ftp-upload'&&row.path===remotePath);assert.ok(upload,'S10_PUBLIC_REQUIRES_ACTUAL_STOR');const assetId=url.pathname.split('/').at(-1)?.slice(0,36);assert.ok(runs.some(run=>run.productId===owner.productId&&run.draftId===owner.draftId&&run.status==='COMPLETED'&&run.slots?.some(slot=>slot.approvedAssetId===assetId&&slot.approvedSha256===upload.bodySha256)),'S10_HOSTED_ASSET_OWNER');const actual=await provider.readFtp(remotePath);assert.equal(sha(actual),upload.bodySha256);protocol={kind:'public-image',remotePath,sha256:upload.bodySha256};response={fromFtpPath:remotePath,contentType:'image/png'};
  }else{
    const folder=join(workspace,'image-generation','candidates'),ids=(await readdir(folder)).filter(id=>uuid.test(id)),candidates=await Promise.all(ids.map(async id=>{const candidate=JSON.parse((await ownedFile(workspace,join(folder,id,'candidate.json'),32768)).toString());assert.equal(candidate.id,id);return candidate;}));
    let candidate;if(input.url==='https://green-cip.cn-shanghai.aliyuncs.com/'&&headers.get('x-acs-action')==='DescribeUploadToken'){
assert.equal(input.method,'POST');assert.equal(bytes.length,0);const pending=runs.filter(run=>run.productId===owner.productId&&run.draftId===owner.draftId&&run.status==='RUNNING').flatMap(run=>run.reviewRequests??[]).filter(request=>request.step==='risk'&&request.state==='SENT_UNKNOWN'&&request.effects[0].state==='PERMITTED'&&request.effects[1].state==='UNPERMITTED');assert.equal(pending.length,1,'S10_TOKEN_REVIEW_OWNER');candidate=candidates.find(row=>row.id===pending[0].candidate.id);assert.ok(candidate);assert.equal(candidate.sha256,pending[0].candidate.sha256);protocol={kind:'acs3',action:'DescribeUploadToken',version:'2022-03-02',contentType:'application/x-www-form-urlencoded',bodySha256:sha(bytes)};response={json:{Code:200,Data:{AccessKeyId:'s10-temporary-id',AccessKeySecret:'s10-temporary-secret',SecurityToken:'s10-temporary-token',BucketName:'s10-normal-bucket',FileNamePrefix:'s10/',OssInternetEndPoint:'https://oss-cn-shanghai.aliyuncs.com',Expiration:Math.floor(Date.now()/1000)+1800}}};
}else if(url.origin==='https://s10-normal-bucket.oss-cn-shanghai.aliyuncs.com'){assert.equal(input.method,'PUT');const id=url.pathname.slice(5,-4);assert.ok(uuid.test(id));candidate=candidates.find(row=>row.id===id);assert.ok(candidate);assert.equal(url.pathname,'/s10/'+candidate.id+'.png');protocol={kind:'oss4',bucket:'s10-normal-bucket',region:'cn-shanghai',candidateId:candidate.id,objectName:'s10/'+candidate.id+'.png',contentType:'image/png',bodySha256:sha(bytes),accessKeyId:'s10-temporary-id',accessKeySecret:'s10-temporary-secret',securityToken:'s10-temporary-token',now:config.clock};response={bytes:Buffer.alloc(0)};
    }else if(input.url==='https://ocr-api.cn-hangzhou.aliyuncs.com/?Type=Commerce'){assert.equal(input.method,'POST');candidate=candidates.find(row=>row.sha256===sha(bytes));assert.ok(candidate,'S10_OCR_CANDIDATE');protocol={kind:'acs3',action:'RecognizeAllText',version:'2021-07-07',contentType:'application/octet-stream',bodySha256:sha(bytes)};response={json:{Code:'success',RequestId:'s10-normal-ocr-'+candidate.id,Data:{Width:candidate.width,Height:candidate.height,Content:provider.normalImageText(candidate.requestId),SubImageCount:0,SubImages:[]}}};
    }else if(input.url==='https://green-cip.cn-shanghai.aliyuncs.com/'&&headers.get('x-acs-action')==='ImageModeration'){
      assert.equal(input.method,'POST');const parameters=new URLSearchParams(bytes.toString());assert.equal(parameters.get('Service'),'aigcViolationDetection');const values=JSON.parse(parameters.get('ServiceParameters'));candidate=candidates.find(row=>row.id===values.dataId);assert.ok(candidate);assert.equal(bytes.toString(),new URLSearchParams({Service:'aigcViolationDetection',ServiceParameters:JSON.stringify({ossBucketName:'s10-normal-bucket',ossObjectName:'s10/'+candidate.id+'.png',ossRegionId:'cn-shanghai',dataId:candidate.id})}).toString());assert.ok(provider.ledger().some(row=>row.event==='request'&&row.publicUrlSha256===sha('https://s10-normal-bucket.oss-cn-shanghai.aliyuncs.com/s10/'+candidate.id+'.png')&&row.bodySha256===candidate.sha256&&row.protocolVerified===true),'S10_MODERATION_REQUIRES_UPLOAD');protocol={kind:'acs3',action:'ImageModeration',version:'2022-03-02',contentType:'application/x-www-form-urlencoded',bodySha256:sha(bytes)};response={json:{Code:200,RequestId:'s10-normal-risk-'+candidate.id,Data:{DataId:candidate.id,RiskLevel:'none',Result:[{Label:'nonLabel',Description:'Synthetic none'}]}}};
    }else throw Error('S10_DYNAMIC_ROUTE_DENIED');
    assert.equal(candidate.productId,owner.productId);const step=protocol.action==='RecognizeAllText'?'ocr':'risk',effect=protocol.kind==='oss4'?'upload':protocol.action==='DescribeUploadToken'?'token':protocol.action==='ImageModeration'?'moderation':'ocr';const active=runs.filter(run=>run.productId===owner.productId&&run.productRevision===candidate.productRevision&&run.draftId===owner.draftId&&run.status==='RUNNING').flatMap(run=>run.reviewRequests??[]).filter(request=>request.step===step&&request.state==='SENT_UNKNOWN'&&request.candidate.id===candidate.id&&request.candidate.sha256===candidate.sha256&&request.effects.some(row=>row.kind===effect&&row.state==='PERMITTED'));assert.equal(active.length,1,'S10_EFFECT_CURRENT_REVIEW_OWNER');const actual=await ownedFile(workspace,join(folder,candidate.id,'image.png'),20*1024*1024);assert.equal(sha(actual),candidate.sha256);assert.equal(actual.length,candidate.byteSize);if(protocol.kind==='oss4'||protocol.action==='RecognizeAllText')assert.equal(sha(bytes),candidate.sha256);
    if(protocol.kind==='acs3'){const now=new Date(headers.get('x-acs-date')).toISOString();assert.ok(Date.parse(now)>=Date.parse(config.clock)-1000&&Date.parse(now)<=Date.now()+1000);Object.assign(protocol,{accessKeyId:config.keys.accessKeyId,accessKeySecret:config.keys.accessKeySecret,now,nonce:config.nonce});}
if(protocol.kind==='oss4'){const raw=headers.get('x-oss-date');assert.match(raw,/^[0-9]{8}T[0-9]{6}Z$/);const now=raw.slice(0,4)+'-'+raw.slice(4,6)+'-'+raw.slice(6,8)+'T'+raw.slice(9,11)+':'+raw.slice(11,13)+':'+raw.slice(13,15)+'.000Z';assert.ok(Date.parse(now)>=Date.parse(config.clock)-1000&&Date.parse(now)<=Date.now()+1000);protocol.now=now;}
  }
  const id='normal-dynamic-'+sha(input.url+input.method+sha(bytes)+headerHash(headers)).slice(0,32);return {route:{id,method:input.method,path:'/normal/dynamic/'+id,publicUrl:input.url,protocol,native:true},response,bytes,headers};
}
